/** Same reserved-first lookup as Program.nativeServiceTy; no local type-code policy. */
export const serviceTypeFor = (key: ServiceKey): { readonly ty: Ty; readonly rendered: string } | undefined => {
  const reserved = serviceTypes.reserved.find(entry => entry.key.name.value === key.name.value && entry.key.service.value === key.service.value)
  if (reserved !== undefined) return reserved
  if (key.name.value < serviceTypes.firstFreeName) return undefined
  return serviceTypes.ordinary.find(entry => entry.code === key.service.value)
}
